// Pour chaque entreprise à contacter (jusqu'à 2 par passage, 10 par jour) : pré-sélection des offres
// ouvertes de son département ou de sa région ayant au moins un mot en commun avec son activité.
// L'IA choisit ensuite la meilleure (ou aucune) à l'étape suivante.
const L=$('Lire les entreprises'),O=$('Lire les offres ouvertes de la zone'),S=$('Compter les envois du jour');
if([L,O,S].some(n=>n.all().some(i=>i.json?.error)))throw new Error('Erreur Supabase : vérifier credentials et colonnes.');
const leads=L.all().map(i=>i.json||{}).filter(x=>x.email&&x.siren&&x.siret), sent=new Set(S.all().map(i=>i.json||{}).filter(x=>x.siret).map(x=>x.siret)).size, slots=Math.max(0,Math.min(2,10-sent)); if(!slots)return [];
const now=Date.now(), vusO=new Set(), offers=O.all().map(i=>i.json||{}).filter(o=>o.avis_id&&!vusO.has(o.avis_id)&&vusO.add(o.avis_id)).filter(o=>o.avis_id&&Date.parse(o.limite||'')>now);
const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim(), dep=s=>String(s||'').trim().toUpperCase().replace(/^([0-9])$/,'0$1');
const rg={'ARA':'01 03 07 15 26 38 42 43 63 69 73 74','BFC':'21 25 39 58 70 71 89 90','BRE':'22 29 35 56','CVL':'18 28 36 37 41 45','COR':'2A 2B','GES':'08 10 51 52 54 55 57 67 68 88','HDF':'02 59 60 62 80','IDF':'75 77 78 91 92 93 94 95','NOR':'14 27 50 61 76','NAQ':'16 17 19 23 24 33 40 47 64 79 86 87','OCC':'09 11 12 30 31 32 34 46 48 65 66 81 82','PDL':'44 49 53 72 85','PAC':'04 05 06 13 83 84'}, region=d=>Object.entries(rg).find(([,v])=>v.split(' ').includes(dep(d)))?.[0];
const VIDES=new Set(['accord','cadre','accordcadre','bons','commande','commandes','relatif','relative','relatifs','relatives','concernant','portant','objet','lots','attribution','consultation','procedure','adaptee','ouverte','realisation','execution','mise','oeuvre','ensemble','besoins','annee','annees','durée','duree','mois','reconductible','reconduction','territoire','departemental','departementale','conseil','regional','regionale','metropole','agglomeration','communaute','communes','syndicat','centre','hospitalier','etablissement','etablissements','batiment','batiments','sites','divers','differents','assistance','accompagnement','missions','mission','gestion','entreprise','activite','activites','marche','marches','public','publics','travaux','service','services','autres','autre','pour','avec','dans','divers','diverses','fourniture','fournitures','prestation','prestations','commune','ville','departement','general','generale','sarl','societe']);
const words=s=>new Set(norm(s).split(' ').filter(w=>w.length>3&&!VIDES.has(w)));
const out=[];let n=0;
for(const e of leads){
  if(n>=slots)break;
  // toutes les offres encore ouvertes de la zone ; une entreprise écartée est revue 3 jours plus tard
  const fresh=offers, checkedAt=new Date().toISOString();
  if(!fresh.length)continue;
  const ed=dep(e.departement||e.code_departement), ew=words([e.domaine_activite,e.secteur].join(' ')), es=words(e.source_marche);
  const ms=fresh.map(o=>{const ds=(Array.isArray(o.departements)?o.departements:String(o.departements||'').split(/[,; ]+/)).map(dep).filter(Boolean), ow=words([o.objet,o.descripteurs,o.type_marche].join(' '));let ka=0,ks=0;for(const w of ew)if(ow.has(w))ka++;for(const w of es)if(!ew.has(w)&&ow.has(w))ks++;const k=ka*2+ks, ok=ka>=1||ks>=2;const same=ds.includes(ed),near=ds.some(d=>region(d)&&region(d)===region(ed));return{o,ds,k,ok,g:same?2:near?1:0}})
    .filter(x=>x.ok&&x.g).sort((a,b)=>(b.k*10+b.g)-(a.k*10+a.g)).slice(0,10);
  if(!ms.length){out.push({json:{action:'non_envoye',id:e.siret,checkedAt}});continue}
  out.push({json:{action:'send',checkedAt,lead:{siret:e.siret,siren:e.siren,email:e.email,nom:e.nom||e.raison_sociale||'',dirigeant:String(e.dirigeant||'').trim(),
    ville:e.ville||'',departement:ed,secteur:e.secteur||'',domaine_activite:e.domaine_activite||'',source_marche:e.source_marche||'',date_attribution:e.date_attribution||''},
    candidats:ms.map(x=>({avis_id:x.o.avis_id,objet:x.o.objet||'',acheteur:x.o.acheteur||'',type_marche:x.o.type_marche||'',departements:x.ds,
      dep_proche:x.ds.includes(ed)?ed:(x.ds.find(d=>region(d)===region(ed))||x.ds[0]||''),montant:x.o.montant,limite:x.o.limite,url:x.o.url||'',lieu:x.o.lieu||''}))}});
  n++;
}
return out;

// Demande à l'IA (OpenAI gpt-4o-mini) de choisir l'offre qui correspond vraiment au métier de l'entreprise, et de la résumer.
const x=$input.item.json, e=x.lead;
const metier=String(e.secteur||'').split('—').pop().trim()||e.domaine_activite||'non précisée';
const liste=x.candidats.map((c,i)=>`${i+1}. [${c.type_marche||'type non précisé'}] ${c.objet} — acheteur : ${c.acheteur||'non précisé'} — département ${c.dep_proche}`).join('\n');
const marche=e.source_marche?`\nMarché déjà remporté par l'entreprise : ${e.source_marche}`:'';
const consigne="Tu aides une entreprise à repérer un marché public auquel elle pourrait vraiment répondre. On te donne son activité et une liste de consultations numérotées.\n"
+"1. Déduis d'abord précisément le métier de l'entreprise à partir de son activité et du marché qu'elle a déjà remporté. Attention aux mots à double sens : « ménages » peut désigner des foyers (accompagnement social, logement) et non du nettoyage.\n"
+"2. Choisis la consultation dont l'objet correspond vraiment à ce métier, c'est-à-dire un marché dont cette entreprise pourrait réaliser ou fournir elle-même l'essentiel. Être du même secteur ne suffit pas : un vendeur de batteries ne répond pas à un marché de camions, un imprimeur ne répond pas à un marché de conseil. Une entreprise de services ou de travaux ne répond pas à un marché de simple fourniture de produits, sauf si vendre ces produits est son métier. Donne une note de 0 à 10 : 10 = cœur de métier, 8 = l'entreprise réalise couramment ce type de prestation, moins de 8 = autre métier ou simple secteur voisin. Si aucune ne mérite au moins 8, réponds choix 0.\n"
+"3. Donne un titre court et clair à la consultation choisie (8 à 14 mots, sans le nom de l'acheteur), par exemple « Nettoyage des locaux et de la vitrerie de l'office de tourisme ».\n"
+"4. Écris un résumé factuel de cette même consultation choisie (et d'aucune autre), en une phrase de 20 à 35 mots, qui décrit ce que l'acheteur recherche, dans une phrase française complète et naturelle. Commence par le nom de l'acheteur écrit normalement (pas en majuscules) ou par « L'acheteur ». Ne dis jamais que l'entreprise propose, fournit ou fait quelque chose. N'invente aucune information (pas de montant, pas de date, pas de durée si elles ne sont pas données).\n"
+'Réponds uniquement en JSON : {"metier": "<métier de l’entreprise en 5 mots>", "choix": <numéro ou 0>, "note": <0 à 10>, "raison": "<10 mots maximum>", "titre": "<titre court de la consultation choisie>", "resume": "<la phrase sur la consultation choisie>"}';
const question=`Entreprise : ${e.nom}\nActivité : ${metier}${e.domaine_activite&&!metier.includes(e.domaine_activite)?' ('+e.domaine_activite+')':''}${marche}\nVille : ${e.ville||'?'} (${e.departement})\n\nConsultations :\n${liste}`;
return {json:{...x,openaiBody:{model:'gpt-4o-mini',temperature:0.1,response_format:{type:'json_object'},messages:[{role:'system',content:consigne},{role:'user',content:question}]}}};

const x = $input.item.json, e = x.lead, o = x.offre;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const DEPS = '01 Ain|02 Aisne|03 Allier|04 Alpes-de-Haute-Provence|05 Hautes-Alpes|06 Alpes-Maritimes|07 Ardèche|08 Ardennes|09 Ariège|10 Aube|11 Aude|12 Aveyron|13 Bouches-du-Rhône|14 Calvados|15 Cantal|16 Charente|17 Charente-Maritime|18 Cher|19 Corrèze|2A Corse-du-Sud|2B Haute-Corse|21 Côte-d’Or|22 Côtes-d’Armor|23 Creuse|24 Dordogne|25 Doubs|26 Drôme|27 Eure|28 Eure-et-Loir|29 Finistère|30 Gard|31 Haute-Garonne|32 Gers|33 Gironde|34 Hérault|35 Ille-et-Vilaine|36 Indre|37 Indre-et-Loire|38 Isère|39 Jura|40 Landes|41 Loir-et-Cher|42 Loire|43 Haute-Loire|44 Loire-Atlantique|45 Loiret|46 Lot|47 Lot-et-Garonne|48 Lozère|49 Maine-et-Loire|50 Manche|51 Marne|52 Haute-Marne|53 Mayenne|54 Meurthe-et-Moselle|55 Meuse|56 Morbihan|57 Moselle|58 Nièvre|59 Nord|60 Oise|61 Orne|62 Pas-de-Calais|63 Puy-de-Dôme|64 Pyrénées-Atlantiques|65 Hautes-Pyrénées|66 Pyrénées-Orientales|67 Bas-Rhin|68 Haut-Rhin|69 Rhône|70 Haute-Saône|71 Saône-et-Loire|72 Sarthe|73 Savoie|74 Haute-Savoie|75 Paris|76 Seine-Maritime|77 Seine-et-Marne|78 Yvelines|79 Deux-Sèvres|80 Somme|81 Tarn|82 Tarn-et-Garonne|83 Var|84 Vaucluse|85 Vendée|86 Vienne|87 Haute-Vienne|88 Vosges|89 Yonne|90 Territoire de Belfort|91 Essonne|92 Hauts-de-Seine|93 Seine-Saint-Denis|94 Val-de-Marne|95 Val-d’Oise|971 Guadeloupe|972 Martinique|973 Guyane|974 La Réunion|976 Mayotte';
const NOMS = Object.fromEntries(DEPS.split('|').map(s => [s.slice(0, s.indexOf(' ')), s.slice(s.indexOf(' ') + 1)]));
const depTxt = d => NOMS[d] ? `${NOMS[d]} (${d})` : (d ? 'le ' + d : 'votre région');
const MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
const dateTxt = s => {
  const t = new Date(s); if (!s || isNaN(t)) return 'non précisée';
  let p; try { p = Object.fromEntries(new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', day: 'numeric', month: 'numeric', year: 'numeric', hour: 'numeric', minute: 'numeric', hour12: false }).formatToParts(t).map(x => [x.type, x.value])); }
  catch (err) { p = { day: t.getUTCDate(), month: t.getUTCMonth() + 1, year: t.getUTCFullYear(), hour: t.getUTCHours(), minute: t.getUTCMinutes() }; }
  const h = Number(p.hour) % 24, m = Number(p.minute);
  return `${Number(p.day)} ${MOIS[Number(p.month) - 1]} ${p.year}` + (h || m ? ` à ${h} h${m ? ' ' + String(m).padStart(2, '0') : ''}` : '');
};
const montantTxt = v => { const n = Number(v); return !v || isNaN(n) || n <= 0 ? 'non communiqué' : n >= 1e6 ? (n / 1e6).toLocaleString('fr-FR', { maximumFractionDigits: 1 }) + ' M€ HT' : Math.round(n).toLocaleString('fr-FR') + ' € HT'; };
// l'annuaire donne souvent les noms en MAJUSCULES : « MARTIN PAYSAGES » -> « Martin Paysages » (sigles gardés : SAS, BTP…)
const PETITS = new Set(['de', 'du', 'des', 'et', 'en', 'sur', 'aux']);
const SIGLES = new Set(['sa', 'sas', 'sasu', 'sarl', 'eurl', 'sci', 'snc', 'scop', 'sel', 'selarl', 'btp', 'tp', 'vrd', 'gie', 'ets', 'cvc']);
const joli = s => { s = String(s || '').trim(); if (!s || s !== s.toUpperCase()) return s;
  return s.toLowerCase().split(/(\s+|-|'|’)/).map((w, i) => !/[a-zà-ÿ]/.test(w) ? w : SIGLES.has(w) ? w.toUpperCase() : (i && PETITS.has(w)) ? w : (i > 1 && w.length === 1) ? w : w.charAt(0).toUpperCase() + w.slice(1)).join(''); };
const court = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + '…' : s; };

const prenom = e.dirigeant ? joli(e.dirigeant.split(/\s+/)[0].toUpperCase()) : '';
const co = joli(e.nom) || 'votre entreprise';
const metierBrut = String(e.secteur || '').split('—').pop().trim() || e.domaine_activite || '';
const metier = metierBrut ? metierBrut.charAt(0).toLowerCase() + metierBrut.slice(1) : '';
const lieu = depTxt(o.dep_proche);
const acheteur = joli(o.acheteur) || 'non précisé';
// titre : celui proposé par l'IA, sinon l'objet s'il est court, sinon sa première phrase
const resume = (() => { const a = String(o.acheteur || ''); let r = String(x.resume || ''); if (a && a === a.toUpperCase() && r.startsWith(a)) r = joli(a) + r.slice(a.length); return r.replace(/\b([A-ZÀ-Ý]{4,}(?:\s+[A-ZÀ-Ý']{2,}){2,})\b/g, m => joli(m)); })();
const titre = x.titre || (() => { const ob = String(o.objet || '').replace(/\s+/g, ' ').trim(); if (ob.length <= 140) return ob;
  const m = ob.match(/(?:porte sur|a pour objet|concerne|consiste en)\s+(?:la |le |les |l['’]|des |du )?([^.;]{10,})/i);
  if (m) return court(m[1].charAt(0).toUpperCase() + m[1].slice(1), 110);
  return court(ob.split(/[.;:]\s/)[0], 110); })();
const date = dateTxt(o.limite), montant = montantTxt(o.montant);
const SITE = 'https://lumen-marche.fr/', INSCRIPTION = SITE + 'inscription.html';
const LOGO = 'https://lumen-marche.fr/logo-email.png?v=3', LOGO_ICONE = 'https://lumen-marche.fr/logo-icone.png?v=2';
const LEGAL = 'Lumen IA, SIRET 985 215 474 00018, 205 chemin de la Halte, 13090 Aix-en-Provence · lumeniaindustrie@gmail.com';

const bonjour = prenom ? `Bonjour ${prenom},` : 'Bonjour,';
const accroche = e.source_marche
  ? `J’ai vu que ${co} avait récemment remporté le marché « ${court(e.source_marche, 110)} ». Une autre consultation en cours pourrait vous intéresser :`
  : `Une consultation publique en cours pourrait intéresser ${co} :`;
const pitch1 = `Lumen repère pour vous les appels d’offres publics qui correspondent à votre métier et à votre secteur géographique, sur le BOAMP et 8 autres plateformes.`;
const pitch2 = `Vous les recevez par email chaque matin, du lundi au vendredi, et notre IA peut analyser le dossier de consultation à votre place. Plus besoin de les chercher vous-même.`;
const pitch = pitch1 + ' ' + pitch2;
const subject = prenom ? `${prenom}, une consultation publique pour ${co}` : `${co} : une consultation publique qui pourrait vous intéresser`;

const t = [bonjour, '', accroche, '', titre, resume, '', 'Acheteur : ' + acheteur, 'Lieu : ' + lieu, 'Montant : ' + montant, 'Date limite : ' + date,
  o.url ? 'Voir l’avis : ' + o.url : '', '', pitch, '', 'Essayez gratuitement pendant 7 jours : ' + INSCRIPTION, '', 'Bien cordialement,', 'Marin Sauzay', 'Fondateur de Lumen Marchés', SITE, '',
  'Pour ne plus recevoir de messages de Lumen, répondez simplement « STOP ».', LEGAL].filter((l, i, a) => l !== '' || a[i - 1] !== '');

const ligne = (k, v) => `<tr><td style="padding:3px 0;color:#6B7280;width:110px;vertical-align:top;">${k}</td><td style="padding:3px 0;color:#171A21;font-weight:600;">${esc(v)}</td></tr>`;
const htmlContent = `<!doctype html>
<html><head><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"></head>
<body style="margin:0;padding:0;background:#F6F7F9;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F7F9;padding:28px 0;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:14px;overflow:hidden;border:1px solid #E6E8EC;">
  <tr><td style="padding:18px 28px;border-bottom:1px solid #E6E8EC;">
    <img src="${LOGO}" width="196" height="41" alt="Lumen Marchés" style="display:block;border:0;width:196px;height:41px;">
  </td></tr>
  <tr><td style="padding:30px 32px 8px;">
    <p style="margin:0 0 16px;font-size:15px;color:#171A21;">${esc(bonjour)}</p>
    <p style="margin:0 0 20px;font-size:15px;line-height:1.6;color:#171A21;">${esc(accroche)}</p>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2FC;border-radius:10px;margin-bottom:22px;"><tr><td style="padding:20px 22px;">
      <p style="margin:0 0 10px;font-size:12px;font-weight:700;color:#2350C4;text-transform:uppercase;letter-spacing:.04em;">Consultation en cours</p>
      <p style="margin:0 0 8px;font-size:15px;line-height:1.4;font-weight:700;color:#171A21;">${esc(titre)}</p>
      <p style="margin:0 0 14px;font-size:14px;line-height:1.55;color:#4B5563;">${esc(resume)}</p>
      <table role="presentation" cellpadding="0" cellspacing="0" style="font-size:13px;width:100%;">
        ${ligne('Acheteur', acheteur)}${ligne('Lieu', lieu)}${ligne('Montant', montant)}${ligne('Date limite', date)}
      </table>
      ${o.url ? `<p style="margin:14px 0 0;font-size:13px;"><a href="${esc(o.url)}" style="color:#2350C4;font-weight:600;text-decoration:none;">Voir l’avis officiel →</a></p>` : ''}
    </td></tr></table>
    <p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#171A21;">${esc(pitch1)}</p>
    <p style="margin:0 0 24px;font-size:15px;line-height:1.6;color:#171A21;">${esc(pitch2)}</p>
    <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td style="border-radius:8px;background:#2350C4;">
      <a href="${INSCRIPTION}" style="display:inline-block;padding:13px 26px;font-size:14px;font-weight:700;color:#FFFFFF;text-decoration:none;border-radius:8px;">Essayer gratuitement 7 jours</a>
    </td></tr></table>
    <p style="margin:0;font-size:15px;color:#171A21;">Bien cordialement,</p>
  </td></tr>
  <tr><td style="padding:4px 32px 28px;">
    <table role="presentation" cellpadding="0" cellspacing="0" style="border-top:1px solid #E6E8EC;width:100%;"><tr>
      <td style="padding-top:18px;vertical-align:middle;width:56px;"><img src="${LOGO_ICONE}" width="40" height="29" alt="Lumen" style="display:block;border:0;width:40px;height:29px;"></td>
      <td style="padding-top:18px;vertical-align:middle;padding-left:14px;border-left:1px solid #E6E8EC;font-size:13px;color:#171A21;line-height:1.5;">
        <b>Marin Sauzay</b><br>Fondateur de Lumen Marchés<br><a href="${SITE}" style="color:#2350C4;text-decoration:none;">lumen-marche.fr</a>
      </td></tr></table>
  </td></tr>
  <tr><td style="background:#F6F7F9;padding:16px 32px;border-top:1px solid #E6E8EC;">
    <p style="margin:0;font-size:12px;color:#6B7280;">Pour ne plus recevoir de messages de Lumen, répondez simplement « STOP ».</p>
    <p style="margin:6px 0 0;font-size:11px;color:#9CA3AF;">${LEGAL}</p>
  </td></tr>
</table></td></tr></table></body></html>`;

return { json: { entreprise_id: e.siret, siren: e.siren, email: e.email, entreprise: co, dirigeant: e.dirigeant, offer_id: o.avis_id, subject, textContent: t.join('\n'), htmlContent } };

// Lit le choix de l'IA : offre retenue (-> email) ou aucune (-> l'entreprise sera revue quand de nouvelles offres arriveront).
const r=$input.item.json, x=$('Préparer résumé IA').item.json;
let rep={}; try{rep=JSON.parse(String(r.message?.content||r.choices?.[0]?.message?.content||'{}'));}catch(err){rep={};}
const num=Number(rep.choix), note=Number(rep.note);
const refus=String(rep.raison||rep.metier||'').slice(0,160);
// pas de réponse exploitable, aucune offre, ou note trop faible : on n'écrit pas
if(rep.choix===undefined||!(num>=1&&num<=x.candidats.length)||!(note>=8))return {json:{action:'non_envoye',id:x.lead.siret,checkedAt:x.checkedAt,raison:(isNaN(note)?'':'note '+note+' : ')+refus}};
// {json:{action:'non_envoye',id:x.lead.siret,checkedAt:x.checkedAt,raison:String(rep.raison||'').slice(0,120)}};
const c=x.candidats[num-1];
let resume=String(rep.resume||'').replace(/\s+/g,' ').trim();
// garde-fou : jamais de phrase qui fait parler l'entreprise, sinon résumé neutre
if(!resume||resume.length<30||new RegExp('\\b'+String(x.lead.nom).split(/\s+/)[0].replace(/[^\wÀ-ÿ-]/g,'')+'\\b','i').test(resume)&&/propos|fourni|réalis|assur|offre ses/i.test(resume))
  resume=(c.acheteur&&c.acheteur!==c.acheteur.toUpperCase()?c.acheteur:'L’acheteur public')+' lance une consultation : '+c.objet.replace(/\.$/,'')+'.';
const motsDe=t=>new Set(String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/[^a-z0-9]+/).filter(w=>w.length>4&&!['marche','consultation','prestation','prestations','fourniture','travaux','services','acheteur','recherche','entreprise','commune','realisation'].includes(w)));
const mo=motsDe(c.objet+' '+c.acheteur), partage=t=>[...motsDe(t)].some(w=>mo.has(w));
// le titre ou le résumé parle d'une autre offre que celle choisie : on les remplace par une version tirée de l'avis
const coherent=partage(rep.titre)&&partage(rep.resume);
if(!coherent)return {json:{action:'non_envoye',id:x.lead.siret,checkedAt:x.checkedAt,raison:'texte de l’IA sans rapport avec l’offre choisie : prudence'}};
if(false)resume=(c.acheteur&&c.acheteur!==c.acheteur.toUpperCase()?c.acheteur:'L’acheteur public')+' lance une consultation : '+String(c.objet).replace(/\s+/g,' ').trim().slice(0,160).replace(/\.$/,'')+'.';
let titre=coherent?String(rep.titre||'').replace(/\s+/g,' ').replace(/^[«"']|[»"'.]$/g,'').trim():'';
if(titre.length<15||titre.length>120)titre='';
return {json:{action:'send',checkedAt:x.checkedAt,lead:x.lead,offre:c,resume,titre,raison:String(rep.raison||'').slice(0,120),note,metier:String(rep.metier||'').slice(0,80),coherent}};

// Départements à couvrir : ceux des prospects de ce passage, plus les départements de leur région.
